#!/usr/bin/env python3
"""Generates Sources/TabberCore/EmojiTable.swift from GitHub's gemoji database (MIT).

  curl -sfLo emoji.json https://raw.githubusercontent.com/github/gemoji/master/db/emoji.json
  python3 scripts/generate-emoji-table.py emoji.json
"""
import json, sys

data = json.load(open(sys.argv[1]))
entries = []
for i, e in enumerate(data):
    for alias in e["aliases"]:
        entries.append((alias, e["emoji"], i))
    for tag in e.get("tags", []):
        entries.append((tag, e["emoji"], i + 10000))  # tags rank after aliases

out = [
    "// Generated by scripts/generate-emoji-table.py from github/gemoji (MIT, Copyright (c) 2019 GitHub, Inc.).",
    "// Do not edit by hand.",
    "",
    "enum EmojiTable {",
    "    /// (shortcode or tag, emoji, rank). Lower rank = more common.",
    "    static let entries: [(String, String, Int)] = [",
]
for name, emoji, rank in entries:
    out.append(f'        ("{name}", "{emoji}", {rank}),')
out += ["    ]", "}", ""]
open("Sources/TabberCore/EmojiTable.swift", "w").write("\n".join(out))
print(len(entries), "entries")
